package com.nopilot.aiservice.service;  import com.nopilot.aiservice.config.AiProperties; import com.nopilot.aiservice.util.LanguageDetector;  import org.springframework.stereotype.Component;  import java.util.List; import java.util.Locale; import java.util.Set;  /**  * Second line of defence before embedding. repository-service already filters,  * but the AI Service never trusts its input: it re-checks path, size and content  * so generated files, binaries and minified bundles never cost embedding time.  */ @Component public class AiFileFilter {      /** Lines longer than this indicate minified / generated code. */     static final int MAX_LINE_LENGTH = 2000;      private static final Set<String> EXCLUDED_DIRECTORIES = Set.of(             ".git", ".svn", ".hg", "node_modules", "bower_components", "vendor",             "target", "build", "dist", "out", ".gradle", ".mvn", ".idea", ".vscode",             "venv", ".venv", "__pycache__", ".tox", ".pytest_cache", ".mypy_cache",             "site-packages", "coverage", ".next", ".nuxt"     );      private static final List<String> GENERATED_SUFFIXES =             List.of(".min.js", ".bundle.js", ".chunk.js", ".d.ts");      private final AiProperties properties;      public AiFileFilter(AiProperties properties) {         this.properties = properties;     }      /** @return null if the file may be indexed, otherwise a short reason why it is skipped. */     public String skipReason(String path, String content) {          if (path == null || path.isBlank()) {             return "empty path";         }         if (LanguageDetector.detect(path) == null) {             return "unsupported file type";         }         if (isInExcludedDirectory(path)) {             return "excluded directory";         }          String name = LanguageDetector.fileName(path).toLowerCase(Locale.ROOT);         for (String suffix : GENERATED_SUFFIXES) {             if (name.endsWith(suffix)) {                 return "generated file";             }         }          if (content == null || content.isBlank()) {             return "empty content";         }         if (content.length() > properties.getIngestion().getMaxFileBytes()) {             return "file too large";         }         if (content.indexOf('\0') >= 0) {             return "binary content";         }         if (hasOverlongLine(content)) {             return "minified or generated content";         }         return null;     }      private boolean isInExcludedDirectory(String path) {         String[] segments = path.split("/");         for (int i = 0; i < segments.length - 1; i++) {             if (EXCLUDED_DIRECTORIES.contains(segments[i].toLowerCase(Locale.ROOT))) {                 return true;             }         }         return false;     }      private boolean hasOverlongLine(String content) {         int lineLength = 0;         for (int i = 0; i < content.length(); i++) {             if (content.charAt(i) == '\n') {                 lineLength = 0;             } else if (++lineLength > MAX_LINE_LENGTH) {                 return true;             }         }         return false;     } }
